) {
	return async (args: TArgs): Promise<PromptResult> => {
		const startedAt = Date.now();
		let scope;
		try {
			const argumentKeys = Object.keys(args).filter(
				(key): key is "routine_id" => key === "routine_id",
			);
			const routineId =
				"routine_id" in args && isString(args.routine_id)
					? args.routine_id
					: undefined;
			scope = memoizeObservationScope(
				observer?.start({
					name,
					kind: "prompt",
					argumentKeys,
					argumentPresence: routineId ? { routine_id: true } : {},
					argumentKeyCountBucket: bucketCount(Object.keys(args).length),
				}),
			);
		} catch {
			scope = undefined;
		}

		try {
			const invoke = () => Promise.resolve(handler(args));
			const result = await (scope ? scope.run(invoke) : invoke());
			void scope?.finish({
				outcome: "success",
				durationMs: Date.now() - startedAt,
				result: {
					isError: false,
					hasStructuredContent: false,
					contentCountBucket: bucketCount(result.messages.length),
				},
